using System.Text.Json;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Options;using SenorArroz.Application.Common.Interfaces;using SenorArroz.Application.Common.Models;using SenorArroz.Application.Common.Services;using SenorArroz.Domain.Entities;using SenorArroz.Domain.Enums;using SenorArroz.Infrastructure.Data;
namespace SenorArroz.Infrastructure.Services;
public class WhatsAppDraftService(ApplicationDbContext db,IWhatsAppOrderDraftCalculator calculator,IOptions<SenorArroz.Application.Options.WhatsAppOrderDraftOptions>? options=null,IClock? clock=null)
{
 private static readonly WhatsAppOrderDraftStatus[] Active=[WhatsAppOrderDraftStatus.Building,WhatsAppOrderDraftStatus.AwaitingCustomerData,WhatsAppOrderDraftStatus.AwaitingAddress,WhatsAppOrderDraftStatus.AwaitingPayment,WhatsAppOrderDraftStatus.ReadyForConfirmation];
 public async Task<WhatsAppOrderDraft?> ActiveDraft(int conversationId,CancellationToken ct){var d=await db.WhatsAppOrderDrafts.Include(x=>x.Items).ThenInclude(x=>x.Product).Include(x=>x.Address).ThenInclude(x=>x!.Neighborhood).Include(x=>x.Customer).FirstOrDefaultAsync(x=>x.ConversationId==conversationId&&Active.Contains(x.Status),ct);if(d is null)return null;var activity=d.UpdatedAt!=default?d.UpdatedAt:d.CreatedAt;var cutoff=(clock?.UtcNow??DateTime.UtcNow).AddMinutes(-Math.Max(1,options?.Value.ResumeWindowMinutes??60));if(activity!=default&&activity<cutoff){d.Status=WhatsAppOrderDraftStatus.Expired;d.Version++;await db.SaveChangesAsync(ct);return null;}return d;}
 public async Task<WhatsAppOrderDraft> GetOrCreate(AgentToolExecutionContext c,CancellationToken ct){var d=await ActiveDraft(c.ConversationId,ct);if(d!=null)return d;d=new WhatsAppOrderDraft{ConversationId=c.ConversationId,BranchId=c.BranchId,CustomerId=c.CustomerId,OrderType=OrderType.Delivery,Status=c.CustomerId.HasValue?WhatsAppOrderDraftStatus.Building:WhatsAppOrderDraftStatus.AwaitingCustomerData};db.WhatsAppOrderDrafts.Add(d);try{await db.SaveChangesAsync(ct);}catch(DbUpdateException){db.Entry(d).State=EntityState.Detached;d=await ActiveDraft(c.ConversationId,ct);if(d==null)throw;}return d;}
 public Task<WhatsAppOrderDraft> Recalculate(int id,CancellationToken ct)=>calculator.Recalculate(id,ct);
 public static object Summary(WhatsAppOrderDraft d)=>new{draftId=d.Id,state=d.Status.ToString(),customer=d.Customer?.Name,orderType=d.OrderType?.ToString(),address=d.Address?.AddressText,neighborhood=d.Address?.Neighborhood?.Name,paymentMethod=d.PaymentMethod,items=d.Items.Select(x=>new{draftItemId=x.Id,productId=x.ProductId,name=x.Product.Name,x.Quantity,x.UnitPrice,x.Subtotal,x.Notes}),d.Subtotal,d.DeliveryFee,d.DiscountTotal,d.Total,d.CashReceived,d.ChangeAmount,d.Notes,missing=Missing(d),readyToConfirm=d.Status==WhatsAppOrderDraftStatus.ReadyForConfirmation,version=d.Version};
 public static string[] Missing(WhatsAppOrderDraft d){var x=new List<string>();if(!d.CustomerId.HasValue)x.Add("customer");if(d.Items.Count==0)x.Add("products");if(!d.OrderType.HasValue)x.Add("orderType");if(d.OrderType==OrderType.Delivery&&(!d.AddressId.HasValue||d.Address?.Neighborhood.Active!=true||d.Address.Neighborhood.BranchId!=d.BranchId))x.Add("validCoveredAddress");if(string.IsNullOrWhiteSpace(d.PaymentMethod))x.Add("paymentMethod");return [..x];}
}
public abstract class DraftToolBase(WhatsAppDraftService drafts):IAgentTool{protected WhatsAppDraftService Drafts=>drafts;public abstract string Name{get;}public abstract string Description{get;}public abstract JsonElement ParametersSchema{get;}public string Category=>"order_draft";public virtual bool ModifiesData=>true;public string RiskLevel=>"medium";public abstract Task<AgentToolExecutionResult> ExecuteAsync(AgentToolExecutionContext c,JsonElement a,CancellationToken ct);}
public class GetOrCreateOrderDraftAgentTool(WhatsAppDraftService d):DraftToolBase(d){public override string Name=>"get_or_create_order_draft";public override string Description=>"Obtiene el único borrador activo de la conversación o crea uno.";public override JsonElement ParametersSchema=>Empty;internal static JsonElement Empty=>JsonDocument.Parse("""{"type":"object","properties":{},"additionalProperties":false}""").RootElement.Clone();public override async Task<AgentToolExecutionResult> ExecuteAsync(AgentToolExecutionContext c,JsonElement a,CancellationToken ct){var x=await Drafts.GetOrCreate(c,ct);return new(true,WhatsAppDraftService.Summary(x),null,"draft_found");}}
public class GetOrderDraftAgentTool(WhatsAppDraftService d):DraftToolBase(d){public override string Name=>"get_order_draft";public override string Description=>"Devuelve el resumen y datos faltantes del borrador activo.";public override bool ModifiesData=>false;public override JsonElement ParametersSchema=>GetOrCreateOrderDraftAgentTool.Empty;public override async Task<AgentToolExecutionResult> ExecuteAsync(AgentToolExecutionContext c,JsonElement a,CancellationToken ct){var x=await Drafts.ActiveDraft(c.ConversationId,ct);return x==null?new(false,null,"Borrador no encontrado.","draft_not_found"):new(true,WhatsAppDraftService.Summary(x),null,"draft_found");}}
public class SetOrderTypeAgentTool(WhatsAppDraftService d,ApplicationDbContext? db=null):DraftToolBase(d){public override string Name=>"set_order_type";public override string Description=>"Define entrega o recogida y recalcula el borrador.";public override JsonElement ParametersSchema=>JsonDocument.Parse("""{"type":"object","properties":{"type":{"type":"string","enum":["delivery","pickup"]}},"required":["type"],"additionalProperties":false}""").RootElement.Clone();public override async Task<AgentToolExecutionResult> ExecuteAsync(AgentToolExecutionContext c,JsonElement a,CancellationToken ct){var x=await Drafts.GetOrCreate(c,ct);var type=a.GetProperty("type").GetString();if(type=="pickup"){var incoming=db is null?null:c.IncomingMessageId.HasValue?await db.WhatsAppMessages.AsNoTracking().Where(m=>m.Id==c.IncomingMessageId&&m.ConversationId==c.ConversationId).Select(m=>m.TextBody).FirstOrDefaultAsync(ct):await db.WhatsAppMessages.AsNoTracking().Where(m=>m.ConversationId==c.ConversationId&&m.Direction==WhatsAppMessageDirection.Inbound).OrderByDescending(m=>m.Timestamp).Select(m=>m.TextBody).FirstOrDefaultAsync(ct);if(!WhatsAppConversationPolicy.IsExplicitPickupRequest(incoming))return new(false,WhatsAppDraftService.Summary(x),"La recogida requiere solicitud expl�cita del cliente.","pickup_requires_explicit_customer_request");}x.OrderType=type=="delivery"?OrderType.Delivery:type=="pickup"?OrderType.Onsite:null;if(x.OrderType==null)return new(false,null,"Tipo no permitido.","invalid_arguments");if(x.OrderType!=OrderType.Delivery)x.AddressId=null;await Drafts.Recalculate(x.Id,ct);x=await Drafts.ActiveDraft(c.ConversationId,ct)??x;return new(true,WhatsAppDraftService.Summary(x),null,"draft_updated");}}
public class AddDraftItemAgentTool(WhatsAppDraftService d,ApplicationDbContext db):DraftToolBase(d){public override string Name=>"add_draft_item";public override string Description=>"Agrega un producto real con precio y disponibilidad actuales; nunca acepta precio.";public override JsonElement ParametersSchema=>JsonDocument.Parse("""{"type":"object","properties":{"productId":{"type":"integer"},"quantity":{"type":"integer","minimum":1,"maximum":50},"notes":{"type":"string","maxLength":500}},"required":["productId","quantity"],"additionalProperties":false}""").RootElement.Clone();public override async Task<AgentToolExecutionResult> ExecuteAsync(AgentToolExecutionContext c,JsonElement a,CancellationToken ct){var id=a.GetProperty("productId").GetInt32();var qty=a.GetProperty("quantity").GetInt32();if(qty is<1 or>50)return new(false,null,"Cantidad inválida.","invalid_arguments");var product=await db.Products.Include(x=>x.Category).FirstOrDefaultAsync(x=>x.Id==id&&x.Category.BranchId==c.BranchId,ct);if(product==null)return new(false,null,"Producto no encontrado.","product_not_found");if(!product.Active||(product.Stock.HasValue&&product.Stock<qty))return new(false,null,"Producto no disponible.","product_unavailable");var draft=await Drafts.GetOrCreate(c,ct);var notes=a.TryGetProperty("notes",out var n)?n.GetString()?.Trim():null;var line=await db.WhatsAppOrderDraftItems.FirstOrDefaultAsync(x=>x.DraftId==draft.Id&&x.ProductId==id&&x.Notes==notes,ct);if(line==null)db.WhatsAppOrderDraftItems.Add(new WhatsAppOrderDraftItem{DraftId=draft.Id,ProductId=id,Quantity=qty,UnitPrice=product.Price,Subtotal=product.Price*qty,Notes=notes});else line.Quantity+=qty;await db.SaveChangesAsync(ct);draft=await Drafts.Recalculate(draft.Id,ct);return new(true,WhatsAppDraftService.Summary(draft),null,"draft_updated");}}
public class RemoveDraftItemAgentTool(WhatsAppDraftService d,ApplicationDbContext db):DraftToolBase(d){public override string Name=>"remove_draft_item";public override string Description=>"Elimina una línea que pertenece al borrador activo.";public override JsonElement ParametersSchema=>JsonDocument.Parse("""{"type":"object","properties":{"draftItemId":{"type":"integer"}},"required":["draftItemId"],"additionalProperties":false}""").RootElement.Clone();public override async Task<AgentToolExecutionResult> ExecuteAsync(AgentToolExecutionContext c,JsonElement a,CancellationToken ct){var draft=await Drafts.ActiveDraft(c.ConversationId,ct);if(draft==null)return new(false,null,"Borrador no encontrado.","draft_not_found");var line=await db.WhatsAppOrderDraftItems.FirstOrDefaultAsync(x=>x.Id==a.GetProperty("draftItemId").GetInt32()&&x.DraftId==draft.Id,ct);if(line==null)return new(false,null,"Línea no encontrada.","draft_item_not_found");db.WhatsAppOrderDraftItems.Remove(line);await db.SaveChangesAsync(ct);draft=await Drafts.Recalculate(draft.Id,ct);return new(true,WhatsAppDraftService.Summary(draft),null,"draft_updated");}}
public class SetDraftNotesAgentTool(WhatsAppDraftService d,ApplicationDbContext db):DraftToolBase(d){public override string Name=>"set_draft_notes";public override string Description=>"Guarda observaciones generales limitadas del borrador.";public override JsonElement ParametersSchema=>JsonDocument.Parse("""{"type":"object","properties":{"notes":{"type":"string","maxLength":1000}},"required":["notes"],"additionalProperties":false}""").RootElement.Clone();public override async Task<AgentToolExecutionResult> ExecuteAsync(AgentToolExecutionContext c,JsonElement a,CancellationToken ct){var x=await Drafts.GetOrCreate(c,ct);var notes=a.GetProperty("notes").GetString()?.Trim();if((notes?.Length??0)>1000)return new(false,null,"Observaciones demasiado largas.","invalid_arguments");x.Notes=notes;x.Version++;await db.SaveChangesAsync(ct);return new(true,WhatsAppDraftService.Summary(x),null,"draft_updated");}}
public class CancelOrderDraftAgentTool(WhatsAppDraftService d,ApplicationDbContext db):DraftToolBase(d){public override string Name=>"cancel_order_draft";public override string Description=>"Cancela de forma idempotente únicamente el borrador activo.";public override JsonElement ParametersSchema=>JsonDocument.Parse("""{"type":"object","properties":{"reason":{"type":"string","maxLength":500}},"additionalProperties":false}""").RootElement.Clone();public override async Task<AgentToolExecutionResult> ExecuteAsync(AgentToolExecutionContext c,JsonElement a,CancellationToken ct){var x=await Drafts.ActiveDraft(c.ConversationId,ct);if(x==null)return new(true,new{cancelled=false},null,"draft_not_found","No había borrador activo.");x.Status=WhatsAppOrderDraftStatus.Cancelled;x.CancelledAt=DateTime.UtcNow;x.CancelledReason=a.TryGetProperty("reason",out var r)?r.GetString()?.Trim():null;x.Version++;await db.SaveChangesAsync(ct);return new(true,new{draftId=x.Id,cancelled=true},null,"draft_cancelled");}}
